3: /// <summary>
4: /// TR-MCP-NUKE-018 (AC-1 to AC-4, AC-6): Contract scenarios and assertions for <see cref="IProviderTestProvisioner"/>.
5: /// A recording fake host stands in for the process environment, the test-database env file, Docker and TCP. The
6: /// expectations come from the acceptance criteria; the fixture secrets are fake markers that must never appear in
7: /// actions or errors. The same assertions run against the scripted mock (BDPv4 mock gate), wrong mocks (negative
8: /// controls), and the production provisioner.
9: /// </summary>
10: internal static class ProviderTestProvisioningContract
11: {
12:     /// <summary>Every scenario name, in the order the contract checks them.</summary>
13:     internal static readonly string[] ScenarioNames =
14:         ["load-from-file", "adopt-set", "file-missing", "variable-missing-in-file", "stopped-container", "missing-container", "unreachable", "localdb-on-linux"];
15: 
16:     /// <summary>Env file path used by every scenario.</summary>
17:     internal const string EnvFile = "/home/fixture/.config/qbrain-test/test-db.env";
18: 
19:     /// <summary>Fake PostgreSQL secret marker.</summary>
20:     internal const string PostgresSecret = "PG_SECRET_VALUE_7";
21: 
22:     /// <summary>Fake SQL Server secret marker.</summary>
23:     internal const string SqlServerSecret = "SQL_SECRET_VALUE_9";
24: 
25:     /// <summary>PostgreSQL connection string in the env file.</summary>
26:     internal const string PostgresValue = "Host=localhost;Port=55432;Username=tester;Password=" + PostgresSecret + ";Database=postgres";
27: 
28:     /// <summary>SQL Server connection string in the env file.</summary>
29:     internal const string SqlServerValue = "Server=localhost,51433;User ID=sa;Password=" + SqlServerSecret + ";TrustServerCertificate=True";
30: 
31:     /// <summary>Env file defining both variables, with a comment, an export prefix and a quoted value.</summary>
32:     internal const string FullEnvFile =
33:         "# QBrain.AI provider test servers\n"
34:         + "export " + ProviderTestNames.PostgresVariable + "=\"" + PostgresValue + "\"\n"
35:         + "\n"
36:         + ProviderTestNames.SqlServerVariable + "=" + SqlServerValue + "\n";
37: 
38:     /// <summary>Builds the fake host of a named scenario.</summary>
39:     internal static FakeProviderTestHost CreateHost(string scenario)
40:     {
41:         var host = new FakeProviderTestHost(scenario);
42:         host.Containers[ProviderTestNames.PostgresContainer] = ProviderTestContainerState.Running;
43:         host.Containers[ProviderTestNames.SqlServerContainer] = ProviderTestContainerState.Running;
44:         host.Containers["sql-server-developer"] = ProviderTestContainerState.Running;
45:         host.Files[EnvFile] = FullEnvFile;
46:         switch (scenario)
47:         {
48:             case "load-from-file":
49:             case "unreachable":
50:                 if (scenario == "unreachable")
51:                 {
52:                     host.Unreachable.Add("localhost:51433");
53:                 }
54: 
55:                 break;
56:             case "adopt-set":
57:                 host.Variables[ProviderTestNames.PostgresVariable] = "Host=db.example;Port=6543;Password=" + PostgresSecret;
58:                 host.Variables[ProviderTestNames.SqlServerVariable] = "Server=tcp:sql.example,1444;Password=" + SqlServerSecret;
59:                 host.Files.Remove(EnvFile);
60:                 break;
61:             case "file-missing":
62:                 host.Files.Remove(EnvFile);
63:                 break;
64:             case "variable-missing-in-file":
65:                 host.Files[EnvFile] = ProviderTestNames.PostgresVariable + "=" + PostgresValue + "\n";
66:                 break;
67:             case "stopped-container":
68:                 host.Containers[ProviderTestNames.PostgresContainer] = ProviderTestContainerState.Stopped;
69:                 break;
70:             case "missing-container":
71:                 host.Containers.Remove(ProviderTestNames.SqlServerContainer);
72:                 break;
73:             case "localdb-on-linux":
74:                 host.Variables[ProviderTestNames.SqlServerVariable] = "Server=(localdb)\\MSSQLLocalDB;Integrated Security=True";
75:                 break;
76:             default:
77:                 throw new InvalidOperationException("Unknown scenario " + scenario);
78:         }
79: 
80:         return host;
81:     }
82: 
83:     /// <summary>Runs one scenario against the provisioner and asserts its contract.</summary>
84:     internal static void AssertScenario(string scenario, IProviderTestProvisioner provisioner)
85:     {
86:         var host = CreateHost(scenario);
87:         var result = provisioner.Provision(EnvFile, host);
88:         var text = string.Join("\n", result.Actions.Concat(result.Errors));
89: 
90:         Assert.DoesNotContain(PostgresSecret, text, StringComparison.Ordinal);
91:         Assert.DoesNotContain(SqlServerSecret, text, StringComparison.Ordinal);
92:         Assert.All(host.ContainerCalls, name => Assert.StartsWith("qbrain-test-", name, StringComparison.Ordinal));
93: 
94:         switch (scenario)
95:         {
96:             case "load-from-file":
97:                 Assert.True(result.Succeeded, string.Join("; ", result.Errors));
98:                 Assert.Equal(PostgresValue, host.Variables[ProviderTestNames.PostgresVariable]);
99:                 Assert.Equal(SqlServerValue, host.Variables[ProviderTestNames.SqlServerVariable]);
100:                 Assert.Empty(host.Started);
101:                 Assert.Contains("localhost:55432", host.Probes);
102:                 Assert.Contains("localhost:51433", host.Probes);
103:                 Assert.Contains("load " + ProviderTestNames.PostgresVariable + " from " + EnvFile, result.Actions);
104:                 Assert.Contains("load " + ProviderTestNames.SqlServerVariable + " from " + EnvFile, result.Actions);
105:                 break;
106:             case "adopt-set":
107:                 Assert.True(result.Succeeded, string.Join("; ", result.Errors));
108:                 Assert.Equal(0, host.ReadFileCalls);
109:                 Assert.Empty(host.ContainerCalls);
110:                 Assert.Empty(host.SetCalls);
111:                 Assert.Contains("db.example:6543", host.Probes);
112:                 Assert.Contains("sql.example:1444", host.Probes);
113:                 Assert.Contains("adopt " + ProviderTestNames.PostgresVariable + " (already set)", result.Actions);
114:                 break;
115:             case "file-missing":
116:                 Assert.False(result.Succeeded);
117:                 Assert.Contains(result.Errors, error => error.Contains(EnvFile, StringComparison.Ordinal));
118:                 Assert.Empty(host.SetCalls);
119:                 Assert.Empty(host.Probes);
120:                 break;
121:             case "variable-missing-in-file":
122:                 Assert.False(result.Succeeded);
123:                 Assert.Contains(result.Errors, error => error.Contains(ProviderTestNames.SqlServerVariable, StringComparison.Ordinal) && error.Contains(EnvFile, StringComparison.Ordinal));
124:                 Assert.Equal(PostgresValue, host.Variables[ProviderTestNames.PostgresVariable]);
125:                 break;
126:             case "stopped-container":
127:                 Assert.True(result.Succeeded, string.Join("; ", result.Errors));
128:                 Assert.Equal(new[] { ProviderTestNames.PostgresContainer }, host.Started);
129:                 Assert.Contains("start " + ProviderTestNames.PostgresContainer, result.Actions);
130:                 break;
131:             case "missing-container":
132:                 Assert.False(result.Succeeded);
133:                 Assert.Contains(result.Errors, error => error.Contains(ProviderTestNames.SqlServerContainer, StringComparison.Ordinal));
134:                 Assert.DoesNotContain(ProviderTestNames.SqlServerContainer, host.Started);
135:                 break;
136:             case "unreachable":
137:                 Assert.False(result.Succeeded);
138:                 Assert.Contains(result.Errors, error => error.Contains("localhost:51433", StringComparison.Ordinal));
139:                 break;
140:             case "localdb-on-linux":
141:                 Assert.False(result.Succeeded);
142:                 Assert.Contains(result.Errors, error => error.Contains(ProviderTestNames.SqlServerVariable, StringComparison.Ordinal) && error.Contains("LocalDB", StringComparison.Ordinal));
143:                 break;
144:             default:
145:                 throw new InvalidOperationException("Unknown scenario " + scenario);
146:         }
147:     }
