149:     /// <summary>Recording fake of <see cref="IProviderTestHost"/>.</summary>
150:     internal sealed class FakeProviderTestHost(string scenario) : IProviderTestHost
151:     {
152:         /// <summary>Scenario name (read by the scripted mock only).</summary>
153:         public string Scenario { get; } = scenario;
154: 
155:         /// <summary>Process environment.</summary>
156:         public Dictionary<string, string> Variables { get; } = new(StringComparer.Ordinal);
157: 
158:         /// <summary>Files by path.</summary>
159:         public Dictionary<string, string> Files { get; } = new(StringComparer.Ordinal);
160: 
161:         /// <summary>Container states by name.</summary>
162:         public Dictionary<string, ProviderTestContainerState> Containers { get; } = new(StringComparer.Ordinal);
163: 
164:         /// <summary>host:port endpoints that refuse connections.</summary>
165:         public HashSet<string> Unreachable { get; } = new(StringComparer.Ordinal);
166: 
167:         /// <summary>Variables set through the boundary.</summary>
168:         public List<string> SetCalls { get; } = [];
169: 
170:         /// <summary>Container names passed to GetContainerState or StartContainer.</summary>
171:         public List<string> ContainerCalls { get; } = [];
172: 
173:         /// <summary>Containers started.</summary>
174:         public List<string> Started { get; } = [];
175: 
176:         /// <summary>host:port endpoints probed.</summary>
177:         public List<string> Probes { get; } = [];
178: 
179:         /// <summary>Number of file reads.</summary>
180:         public int ReadFileCalls { get; private set; }
181: 
182:         /// <inheritdoc />
183:         public string? GetVariable(string name) => Variables.TryGetValue(name, out var value) ? value : null;
184: 
185:         /// <inheritdoc />
186:         public void SetVariable(string name, string value)
187:         {
188:             SetCalls.Add(name);
189:             Variables[name] = value;
190:         }
191: 
192:         /// <inheritdoc />
193:         public string? ReadFile(string path)
194:         {
195:             ReadFileCalls++;
196:             return Files.TryGetValue(path, out var text) ? text : null;
197:         }
198: 
199:         /// <inheritdoc />
200:         public ProviderTestContainerState GetContainerState(string containerName)
201:         {
202:             ContainerCalls.Add(containerName);
203:             return Containers.TryGetValue(containerName, out var state) ? state : ProviderTestContainerState.Missing;
204:         }
205: 
206:         /// <inheritdoc />
207:         public bool StartContainer(string containerName)
208:         {
209:             ContainerCalls.Add(containerName);
210:             if (!Containers.TryGetValue(containerName, out var state) || state == ProviderTestContainerState.Missing)
211:             {
212:                 return false;
213:             }
214: 
215:             Started.Add(containerName);
216:             Containers[containerName] = ProviderTestContainerState.Running;
217:             return true;
218:         }
219: 
220:         /// <inheritdoc />
221:         public bool CanConnect(string host, int port, TimeSpan timeout)
222:         {
223:             var endpoint = host + ":" + port.ToString(System.Globalization.CultureInfo.InvariantCulture);
224:             Probes.Add(endpoint);
225:             return !Unreachable.Contains(endpoint);
226:         }
227:     }
228: }
